// scripts/app-meta.ts — the identity mirror.
//
// `app.meta.json` is the single source of the product's identity (name, slug, identifier,
// version, publisher, repository, licence). Every other copy is a mirror written by this script:
//
//   bun run meta:sync    rewrite every mirror from app.meta.json
//   bun run meta:check   fail (exit 1) if any mirror drifted; writes nothing
//
// Provenance: the idea and the sync/check split come from ZER0 `scripts/app-meta.ts` (MIT).
// This is a compact re-implementation for this workspace, not a copy.
//
// Mirrors are either whole generated files (`src-tauri/src/identity.rs`, `src/lib/identity.ts`)
// or single fields in hand-maintained files, edited structurally (JSON) or by an anchored regex
// (TOML, HTML) that must match exactly once; a missing anchor is an error, never a silent skip.

import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { resolve } from "node:path";

const ROOT = resolve(import.meta.dirname, "..");
const TAG = "[app-meta]";

export interface AppMeta {
  name: string;
  slug: string;
  identifier: string;
  version: string;
  description: string;
  publisher: string;
  repository: string;
  license: string;
}

const REQUIRED: (keyof AppMeta)[] = [
  "name",
  "slug",
  "identifier",
  "version",
  "description",
  "publisher",
  "repository",
  "license",
];

export function readMeta(root = ROOT): AppMeta {
  const raw = JSON.parse(readFileSync(resolve(root, "app.meta.json"), "utf8")) as Record<
    string,
    unknown
  >;
  for (const key of REQUIRED) {
    if (typeof raw[key] !== "string" || (raw[key] as string).length === 0) {
      throw new Error(`app.meta.json: "${key}" must be a non-empty string`);
    }
  }
  const meta = raw as unknown as AppMeta;
  if (!/^\d+\.\d+\.\d+(-[0-9A-Za-z.-]+)?$/.test(meta.version)) {
    throw new Error(`app.meta.json: version "${meta.version}" is not semver`);
  }
  if (!/^[a-z][a-z0-9-]*(\.[a-z][a-z0-9-]*){2,}$/.test(meta.identifier)) {
    throw new Error(`app.meta.json: identifier "${meta.identifier}" is not reverse-DNS`);
  }
  return meta;
}

/** One mirror: a path and a function from (meta, current text) to the expected text. */
interface Mirror {
  path: string;
  render: (meta: AppMeta, current: string | null) => string;
}

const GENERATED_HEADER = "GENERATED by `bun run meta:sync` from app.meta.json. Do not edit.";

function replaceOnce(text: string, re: RegExp, replacement: string, where: string): string {
  const matches = text.match(
    new RegExp(re.source, re.flags.includes("g") ? re.flags : re.flags + "g"),
  );
  if (!matches || matches.length !== 1) {
    throw new Error(
      `${where}: expected exactly one match for ${re}, found ${matches?.length ?? 0}`,
    );
  }
  return text.replace(re, replacement);
}

function editJson(current: string | null, path: string, edit: (j: any) => void): string {
  if (current === null) throw new Error(`${path} is missing`);
  const json = JSON.parse(current);
  edit(json);
  return JSON.stringify(json, null, 2) + "\n";
}

const rustString = (s: string) => JSON.stringify(s);

export const MIRRORS: Mirror[] = [
  {
    path: "package.json",
    render: (m, cur) =>
      editJson(cur, "package.json", (j) => {
        j.name = m.slug;
        j.version = m.version;
      }),
  },
  {
    path: "src-tauri/tauri.conf.json",
    render: (m, cur) =>
      editJson(cur, "tauri.conf.json", (j) => {
        j.productName = m.name;
        j.version = m.version;
        j.identifier = m.identifier;
        if (j.bundle) {
          j.bundle.license = m.license;
          j.bundle.publisher = m.publisher;
        }
      }),
  },
  {
    path: "Cargo.toml",
    render: (m, cur) => {
      if (cur === null) throw new Error("Cargo.toml is missing");
      let t = replaceOnce(cur, /^version = ".*"$/m, `version = "${m.version}"`, "Cargo.toml");
      t = replaceOnce(t, /^license = ".*"$/m, `license = "${m.license}"`, "Cargo.toml");
      t = replaceOnce(
        t,
        /^authors = \[.*\]$/m,
        `authors = [${rustString(m.publisher)}]`,
        "Cargo.toml",
      );
      t = replaceOnce(t, /^repository = ".*"$/m, `repository = "${m.repository}"`, "Cargo.toml");
      return t;
    },
  },
  {
    path: "index.html",
    render: (m, cur) => {
      if (cur === null) throw new Error("index.html is missing");
      return replaceOnce(
        cur,
        /<title>.*<\/title>/,
        `<title>${m.name} Studio</title>`,
        "index.html",
      );
    },
  },
  {
    path: "src-tauri/src/identity.rs",
    render: (m) =>
      [
        `//! Product identity. ${GENERATED_HEADER}`,
        "",
        `// Not every constant has a Rust reader yet; the module is the single source for all of them.`,
        `#![allow(dead_code)]`,
        "",
        `/// Product name shown to people.`,
        `pub const NAME: &str = ${rustString(m.name)};`,
        `/// Lower-case, filesystem- and URL-safe name.`,
        `pub const SLUG: &str = ${rustString(m.slug)};`,
        `/// Reverse-DNS bundle identifier.`,
        `pub const IDENTIFIER: &str = ${rustString(m.identifier)};`,
        `/// Title of the Studio window.`,
        `pub const STUDIO_TITLE: &str = ${rustString(`${m.name} Studio`)};`,
        "",
      ].join("\n"),
  },
  {
    path: "src/lib/identity.ts",
    render: (m) =>
      [
        `// Product identity. ${GENERATED_HEADER}`,
        "",
        `export const NAME = ${JSON.stringify(m.name)};`,
        `export const SLUG = ${JSON.stringify(m.slug)};`,
        `export const IDENTIFIER = ${JSON.stringify(m.identifier)};`,
        `export const VERSION = ${JSON.stringify(m.version)};`,
        `export const REPOSITORY = ${JSON.stringify(m.repository)};`,
        "",
      ].join("\n"),
  },
];

/** Paths `meta:sync` may rewrite; the pre-commit gate stages exactly these. */
export function identityPaths(): string[] {
  return MIRRORS.map((m) => m.path);
}

/** Returns the mirrors whose content differs from what app.meta.json implies. */
export function plan(root = ROOT): { path: string; expected: string; drift: boolean }[] {
  const meta = readMeta(root);
  return MIRRORS.map((mirror) => {
    const abs = resolve(root, mirror.path);
    const current = existsSync(abs) ? readFileSync(abs, "utf8") : null;
    const expected = mirror.render(meta, current);
    return { path: mirror.path, expected, drift: current !== expected };
  });
}

if (import.meta.main) {
  const check = process.argv.includes("--check");
  let results;
  try {
    results = plan();
  } catch (e) {
    console.error(`${TAG} ${(e as Error).message}`);
    process.exit(1);
  }
  const drifted = results.filter((r) => r.drift);
  if (check) {
    if (drifted.length) {
      console.error(`${TAG} identity drift in: ${drifted.map((r) => r.path).join(", ")}`);
      console.error(`${TAG} run \`bun run meta:sync\``);
      process.exit(1);
    }
    console.log(`${TAG} ${results.length} mirrors in sync`);
  } else {
    for (const r of drifted) writeFileSync(resolve(ROOT, r.path), r.expected);
    console.log(
      drifted.length
        ? `${TAG} rewrote ${drifted.map((r) => r.path).join(", ")}`
        : `${TAG} ${results.length} mirrors already in sync`,
    );
  }
}
